                ["es"] = new()
                {
                    [0x036a7ec59a2378aeUL] = "Entendido, Reina B.",
                    [0x04288307a2f02760UL] = "Hola. Quiero denunciar el paradero de un notorio ASESINO EN SERIE.",
                    [0x0635c55daced5862UL] = "¡No voy a quedarme aquí toda la noche!",
                    [0x0e8727e75f2dc91eUL] = "¡No hacer daño a la Reina Balista!",
                    [0x0f5797910f6e4222UL] = "¡Yeee-hawww!",
                    [0x11102a388b0c488aUL] = "Yo.",
                    [0x1822d75d4c4b2a19UL] = "Piedad",
                    [0x18e675a72233298fUL] = "BLOQUE",
                    [0x18e6bef70932509cUL] = "El Espectador",
                    [0x1ed278cd898a56f2UL] = "Ahora eshtoy eshperando a que eshos matonesh vuelvan para liquidarme. No tengo ganash de correr más. Es una maldita cosha trash otra...",
                    [0x1f203f4e59f5cd8dUL] = "La gente de hoy en día...",
                    [0x1f5b7e573cbf4c01UL] = "¡Woooh! ¡Buen tiro, Reina B!",
                    [0x291202ff73e9e072UL] = "El alcalde comentó brevemente el ataque, calificándolo de \"totalmente injusto\". ¡Les traeremos actualizaciones en directo a medida que esta emocionante historia se desarrolla!",
                    [0x29582d73906f8c40UL] = "Pero la lucha entre el Orden y el Caos aún no se ha decidido. El equilibrio cambiará, y nuestros héroes volverán una y otra vez a Sunny City.",
                    [0x29b4fe2dbb57ef6aUL] = "¡¡¡MI VIDA POR BALISTAAAAA!!!",
                    [0x2c9e88d31ec5c7d3UL] = "MetroPoli",
                    [0x2cadd26834d97180UL] = "¡No dejéis que se escapen! ¡HACED algo!",
                    [0x31924c52baa84d6bUL] = "BANDA HIVE",
                    [0x32505ed2615a90cfUL] = "MATA\r\nLOS\r\nTODOS",
                    [0x344caa065b4fa30bUL] = "¿Eh Frank, me prestas un dólar? Quiero comprarme un refresco de la máquina.",
                    [0x345852fa00e98d27UL] = "REINA",
                    [0x3567f1bf42f27991UL] = "¡Eh, sois esos prisioneros! ¿Cómo demonios habéis sobrevivido? Da igual. Veo que no sois amigos de la banda Hive. Así que ayudémonos.",
                    [0x3626754b9f4fce11UL] = "¡Vaya, siguesh vivo! ¡Sube!",
                    [0x39b52944cab631faUL] = "¡Eh, CUIDADO!",
                    [0x3a224d0ee5a8c249UL] = "—¡Sangre! ¡Sangre para BALISTA!",
                    [0x3a9ff2ee65fcda1eUL] = "BANDA HIVE\r\n ¡MOLA!",
                    [0x3dbe25089691de83UL] = "No osh preocupéish. Eshtoy másh firme que una roca. Y VOLARÉ como una, ya veréish.",
                    [0x40cc3f8a39491e51UL] = "¡Eshtá viva! ¡¡ESHTÁ VIVA!! ¡Subid a bordo, tíos!",
                    [0x40fedf513f4bf84fUL] = "BLOQUE DE DETENCIÓN A",
                    [0x431202ac48344bf4UL] = "¡Esta noche solo hay una ley: Haced lo que vuestro odio os dicte!",
                    [0x43f92a5c402137ddUL] = "¡Demasiados... malditos, demasiados!",
                    [0x44cc3f3f7d3fe1e0UL] = "Al menos la electricidad ha vuelto... pero ¿qué demonios pasa con las cámaras?",
                    [0x45112e69a0ede541UL] = "Hay un piloto, prisionero como vosotros. Está en el Bloque de Detención D. Si alguien puede sacaros de este lío, es él. Y puedo llevaros hasta él, pero antes tenéis que ayudarme a matar a Balista.",
                    [0x46633bc8a3feeadaUL] = "¡Maldita shea! Algo va mal con los motoresh. ¿Qué idiota tocó eshto? Dejadme revisar bajo el capó...",
                    [0x4777cc942d9250faUL] = "Pueden decirle a sus hombres que se relajen, detective. Nos encargamos nosotros.",
                    [0x48f915a5bbed5545UL] = "Ruido raro... lo ignoraré.",
                    [0x4cc55697b6b10e11UL] = "¡No os libraréis de mí tan fácil, amantes de cerdos!",
                    [0x4cdedc0731675745UL] = "¡Ese no es el TEMA! ¡Es cuestión de... de PRINCI-PIOS! ¿Dónde estaría la banda Hive si empezáramos a PAGAR por las cosas?",
                    [0x4df8d1bea7423792UL] = "¿Comprar un refresco? ¡¿COMPRAR un refresco?! ¡Eres un MATÓN! ¡Tienes un BATE! ¡¡Revienta la maldita cosa!!",
                    [0x4e52106b24fc9771UL] = "Vale, me habéish convencido. ¡Salgamosh de aquí volando!",
                    [0x4fea2fa39f3b3823UL] = "¡Bien merecido! No sé qué trama McBride, pero es buen policía. Ya quedan pocos en esta ciudad...",
                    [0x51b89fca49d19f7bUL] = "SALIDA",
                    [0x52a5a79ed1d29c03UL] = "Muchos señalan los eventos de esta noche como prueba de la obsolescencia de la fuerza policial tradicional, y de que la aplicación de la ley totalmente privatizada es sin duda el camino del futuro.",
                    [0x5391db195f195110UL] = "¡Una escapada shuave, teniendo en cuenta todo!",
                    [0x54b686163fa4490fUL] = "¡¡RUHAHAAAARRR HUARRRR!!",
                    [0x564396398a82ba28UL] = "MATAR",
                    [0x5954a097af2969f2UL] = "¡...EMERGENCIA! ¡Abandonad la nave!",
                    [0x5a7b270b6fc84783UL] = "Gracias por la ayuda. Será mejor que os larguéis de aquí. Lejos de Sunny City.",
                    [0x5dc60337c07f4fe1UL] = "Sunny City, 20XX\r\n\r\nComisaría 9",
                    [0x5e55eaeb18d2b7c8UL] = " HIVE\r\nGANG\r\n¡MOLA!",
                    [0x60cc6f21806e3e1cUL] = "Mfgllll mfwrrrr! ¡MFWRRRR!",
                    [0x620282fb56b61254UL] = "Umm... no sé, suena a mucho curro... Más fácil...",
                    [0x65d92816d864926eUL] = "A todos mis valientes guerreros, mis fieles berserkers: ¡aplastad los últimos focos de resistencia! ¡Traedme la cabeza del Comisario Hagan!",
                    [0x66d57fd83ba780ceUL] = "¡Se acabó! ¡NO va a entrar NADIE! ¡Por mucho que supliquen!",
                    [0x6b2c32be2d6e8929UL] = "¡Matad también a los prisioneros! ¡Tenemos todos los guerreros que necesitamos!",
                    [0x6d1da39229b50eb2UL] = "Has oído a la dama, poli. ¡Hora de decir buenas noches!",
                    [0x6e2d3cb39ba594cbUL] = "¡BASTARDOS! ¡No os saldréis con la vuestra!",
                    [0x6f48c5680a6578a8UL] = "¡Mueve el culó!",
                    [0x6ffcc22b3a80afd2UL] = "¡Socorro! ¡Va a por mí!",
                    [0x7032c1ee00e8c277UL] = "Jeff",
                    [0x70818f5012b2a6b9UL] = "Vale, veamosh qué hay aquí. Preferiría mi fiel avión, pero... eshto shervirá. Shi pudieshe encontrar el contacto. Ah, aquí eshtá.",
                    [0x70897260e656a02cUL] = "Bloque",
                    [0x72a8dd799de66b83UL] = "SALIDA",
                    [0x74d1004c33a4cf82UL] = "Eshta cosha esh vieja incluso para mí... ¿Dónde va eshta pieza? No, ashi no esh...",
                    [0x76593c4f11889014UL] = "Quiero decir ¿qué sentido tiene shi pueden... hmm... umm... ¿esho es una...?",
                    [0x76bae89ee56047a0UL] = "¡Dios nos salve, es la banda Hive!",
                    [0x794b42e6e43d51acUL] = "Nanay.",
                    [0x80dc943a46520f6cUL] = "¡Jefe! ¡Quiero mi llamada!",
                    [0x87ee43f95113b100UL] = "MATAD\r\nTODOS\r\nLOS POLIS",
                    [0x8ac3573c90cfbc94UL] = "¡¿Así que volverás a mis propios hombres contra mí?! ¡Mala, apestosa, sanguinaria...",
                    [0x8b374962aea1e30eUL] = "¡Ja! ¡Ni hablar!",
                    [0x8b3bc239dedf1bc0UL] = "Mierda, ¡ya vienen! Escuchad. Hay un ascensor por la puerta de atrás. Yo intentaré encontrar otro camino para subir. Nos vemos allí, espero.",
                    [0x8b3bd9f00d1c3605UL] = "¡No! ¿Cómo habéis entrado? ¡¡AYUDA!!",
                    [0x8b8b89dc8de8ecf6UL] = "Matadlos.",
                    [0x8bb41de9553af736UL] = "Hasta entonces, ¿qué queda por decir salvo:\r\nBien jugado, damas y caballeros.",
                    [0x8e781aceec208dfeUL] = "Aquí Balista. Esta comisaría está ahora bajo control de la banda Hive. Todas las salidas están selladas. No hay escapatoria.",
                    [0x8eb45aba1a7af43fUL] = "...con más nieve esperada durante el fin de semana festivo.",
                    [0x8eda0d484d2b9b1aUL] = "¡Ahórrate lash excusas para el jefe, idiota!",
                    [0x919ac2597112e633UL] = "¡Nadie sale, por orden de Balista!",
                    [0x921185c061452504UL] = "¡Muere! ¡Por orden de Balista!",
                    [0x9445dc6be5a3ee7dUL] = "No sé. Quería interrogarlos o algo así. O quizá solo quería fastidiar a esos gusanos corporativos.",
                    [0x993a2f48484a41e2UL] = "¡OYE! ¿Es que no respetáis ni la ley ni el orden?!",
                    [0xa3e0bd0a4c2d32faUL] = "¡Tú... tú... me las...!",
                    [0xa5a988f92c1e63c4UL] = "¿¡Muerto!?\r\n\r\n¡Quienquiera que seas, acabas de cabrear a la banda Hive!",
                    [0xa5e7abbb835df100UL] = "BANDA HIVE",
                    [0xa63fb33072e54399UL] = "Mujer misteriosa",
                    [0xa6584a89b26fe7b3UL] = "MATAD",
                    [0xa6c6d892eb95e471UL] = "¡No dejéis que escapen los activos!",
                    [0xab522c636a0e6128UL] = "¡No osh creeréish cómo shobreviví. ¡Luego osh lo cuento!",
                    [0xafae86a2590e4b00UL] = "¿Me mandáis una postal, vale?",
                    [0xafc7d444ab3a616bUL] = "Shi buscáis mi cerveza, ya no queda. Eshtos maderos me la... me la... quitaron cuando me detuvieron. ¡Me quitaron lash alash, lash bashtardos!",
                    [0xb212b8ea4802f71aUL] = "DERROTA\r\n¡El piloto ha sido asesinado!",
                    [0xb7d3d2d176763a19UL] = "Me llamo Jeffh, por cierto. Sabéish, eshto podría ser el comienzo de una hermosha...",
                    [0xbb5a28cd54f65e38UL] = "Esta retransmisión ha sido patrocinada por MetroCorp: Un Futuro más Brillante para Sunny City. ¡Buenas noches!",
                    [0xbb6a540c1ec0e4f4UL] = "El ejército de matones fanáticos de Balista tomó rápidamente el control de la comisaría y se atrincheró dentro. ¡No está claro si alguien sobrevivió a la bárbara oleada!",
                    [0xbcb3cc0bf22360bdUL] = "¡Aquí Balista! ¡El cobarde de Hagan debe entregarse!",
                    [0xbce92351bca42cf8UL] = "El alcalde considera su departamento... INSUFICIENTE para la situación. Deje esto a los profesionales.",
                    [0xbd1b53ade13daa4dUL] = "¡Contenedlos mientrash trabajo en eshta cosha!",
                    [0xbdd49e2f3d6dd1d1UL] = "Ahora, imagino que toca descansar. Un momento de paz, quizá, más allá de esas colinas oscuras.",
                    [0xc09bbd3d2f3fdbccUL] = "¡Banda de mercenarios de mierda! ¡Pedí refuerzos, POLICÍAS, no una panda de gatillo fácil!",
                    [0xc232981f08e5d7beUL] = "Lo sé PERFECTAMENTE, detective. Buenas noches.",
                    [0xc2df6869edc67547UL] = "MATAD\r\nLOS\r\nA TODOS",
                    [0xc5ad69595973c5cbUL] = "ANARQUÍA",
                    [0xc74a88131e6a22dfUL] = "Hmmm. Primer motor lishto, pero el shegundo también necesitaría un ajushte. ¡Contenedlos un poco másh, tíos!",
                    [0xc8dea6adab5b0254UL] = "OBEDECE",
                    [0xc96a323fc267e0feUL] = "¡Venga, salgamosh de aquí!",
                    [0xcd2a719214a4f9b6UL] = "Balista",
                    [0xcd88fe737dc15abaUL] = "BALISTA\r\n  ES\r\nREINA",
                    [0xcf18e1924041e938UL] = "Quiero todas las salidas selladas. Que nadie entre ni salga. Voy a visitar al Comisario.",
                    [0xd0c865f0a840ceb5UL] = "NO\r\nPiedad",
                    [0xd0ed97895f85a908UL] = "¿Como qué? Ya les estamos disparando. Y nos hemos quedado sin Barredores.",
                    [0xd234a886d21a0080UL] = "¡Ríndete, Balista! ¡Hagan está muerto, ya tienes lo que querías!",
                    [0xd844e8b6c449a9dfUL] = "Alfa tango a zeta foxtrot. Desplieguen los Barredores.",
                    [0xdab28176b0d9658fUL] = " ¡MOLA!",
                    [0xdb046f5df26c80aeUL] = "Probablemente el asalto fue un acto de venganza temerario por una campaña reciente contra el crimen liderada por el Comisario Hagan, en la que murieron varios altos cargos de la banda Hive.",
                    [0xdc9628a2e5dccd50UL] = "AYUDA",
                    [0xdead4285f0b5615aUL] = "Nada. Nunka volveré a volar... másh vale rendirshe y... [gruñidos incomprensibles].",
                    [0xdf5bab3f13c23da7UL] = "La comisaría de la Novena ha sido atacada hoy por la infame banda Hive. Su líder, una mujer conocida solo como Balista, es la autoproclamada reina del crimen desorganizado de nuestra ciudad.",
                    [0xe09dda4e4d949d9dUL] = "¡Además, quien me traiga al comisario, vivo o muerto, se librará de más violencia!",
                    [0xe2a689e0ef6356deUL] = "¿Q-qué demonios está pasando ahí fuera?",
                    [0xe2b3e921c2eb78c8UL] = "¡Eh, eres ese prisionero! ¿Cómo demonios sobreviviste? Da igual. Veo que no eres amigo de la banda Hive. Así que ayudémonos.",
                    [0xe36d733447235e46UL] = "Presentador",
                    [0xe4d737b422a42442UL] = "¿Pero por qué parar ahora cuando me lo eshtoy pasHando TAN... BIEN?",
                    [0xe62825a3f17a8e22UL] = "¡Sí, sí! ¡Baja la voz!",
                    [0xe63446bb533998e4UL] = "¡B-Balista!",
                    [0xe9bb19c6c77ce918UL] = "NO",
                    [0xeb6ea4fbdae67a8dUL] = "BALISTA\r\n  ES\r\nREINA",
                    [0xee11f81195a12305UL] = "Y matad a esa majara por mí, ¿vale?",
                    [0xf0656dbb5ab6cab8UL] = "Claro, señora. ¿Quién?",
                    [0xf0a8e2712d23a8b6UL] = "Última hora: Por orden del alcalde, varias unidades de MetroLaw han sido desplegadas para lidiar con los terroristas que tomaron el control de la comisaría de la Novena esta noche.",
                    [0xf24946686c8545c2UL] = "¿No se rinden, verdad?\r\nQuizá es que no saben cómo.",
                    [0xf563e820c21015beUL] = "Sunny City, 20XX\r\n\r\n",
                    [0xf5aeb95b33b40b2eUL] = "Supongo que tienes razón, Frank... Es importante tener princi-pios.",
                    [0xf784dedff7114627UL] = " ¡MOLA!",
                    [0xfe1e16ae5a0d8fdbUL] = "¿Por qué trajo McBride a esos luchadores renegados? MetroLaw acabará con ellos, no tiene sentido resistirse.",
                },
            },
            ["9981018a-c343-442a-983e-719321c4da59"] = new()
            {
                ["es"] = new()
                {
                    [0x01051dfa0e811b17UL] = "Entendido, alfa 3. Todas las unidades desplegadas, nos acercamos al objetivo.",
                    [0x01d074f6960b333eUL] = "¿Un poco desorientado? ¡No te preocupes!",
                    [0x03975ae59704af11UL] = "¡Tres!",
                    [0x1263fd91b03b820dUL] = "¡Ha llegado el momento, damas y caballeros, de la esperadísima final de temporada de Superfighters Live!",
                    [0x159daaac4f56d7e3UL] = "¡¡¡NO VOY A VOLVER A LA HORA INFANTIL!!!",
                    [0x18bb1c8f44f2b01dUL] = "¡Recuerden - ellos o nosotros!",
                    [0x1a24dee897c52d65UL] = "¡Paren las rotativas!",
                    [0x1f08e947dd01d281UL] = "¡Je je!",
                    [0x21ca3b0f1921b2f0UL] = "¡No pueden tratarnos así!",
                    [0x23f457d3dc9522ebUL] = "¡Dos!",
                    [0x2548fccef3d6e3f0UL] = "¡Buen trabajo ahí fuera! ¡Sí que les diste duro a esos gamberros!",
                    [0x2a75dd56ca6fef83UL] = "Juju juju...",
                    [0x305903dfa72e5681UL] = "Amén a eso.",
                    [0x3228cdb77e06939eUL] = "¡Buen trabajo! ¡Pero ahora empieza la pelea de verdad!",
                    [0x403edcea71ed28f2UL] = "¡Que empiece la pelea!",
                    [0x40520bc2d689e8bfUL] = "¡Yo no me apunté para esto!",
                    [0x40bacd1373b04133UL] = "Figura sombría",
                    [0x421cdc4d883c8583UL] = "¡Nos están alcanzando!",
                    [0x4246cde8955c0d0aUL] = "¿Qué intentan hacer? ¡Aunque destruyan el programa, no pueden hacer volar todo el estudio!",
                    [0x466826e5b94c6438UL] = "¡¿Qué demonios?! ¡¿QUÉ DEMONIOS?!",
                    [0x4833e9b1cf715897UL] = "¿Ah, sí, saco de carne?",
                    [0x548033483ff07773UL] = "¡Arriba y a brillar, superluchadores! ¡Hay trabajo por hacer!",
                    [0x55149a4460de4b70UL] = "...¡y recuerda: QUE TE DIVIERTAS!",
                    [0x558b436a14b705f3UL] = "¡Vamos! El espectáculo está empezando, ¡y tú eres la gran estrella!",
                    [0x57baa73f374e4b28UL] = "¡Gran estrella!\n¡Je je!",
                    [0x585ea9637c40eb85UL] = "Ugh... todos son críticos...",
                    [0x590434a5c8266949UL] = "Pero supongamos que alguien derribara la torre de transmisión. Supongamos que alguien cortara la señal...",
                    [0x593733f7399f7e59UL] = "Se está haciendo tarde.",
                    [0x59a1f17dbbb26892UL] = "¡JUA JUA JUA!",
                    [0x5e527bdbd65a1c2aUL] = "¡Tengo una buena carrera y no voy a dejar que unos idiotas de laboratorio me la arruinen!",
                    [0x5e5bdfb945b89585UL] = "Seguro que te das cuenta de que no vas a salir de este edificio. Todas las salidas están cortadas y vienen más soldados.",
                    [0x6912caa2276adbb7UL] = "¡¿Qué demonios fue eso?!",
                    [0x6aae9fd4dc8010c2UL] = "¡Vamos! ¡El público no muerde! ¡Je je!",
                    [0x6ea9fdd66ed01b03UL] = "¡Lárgate, chaval!",
                    [0x6f6f696a6fd2bd8eUL] = "¿Qué equipo saldrá victorioso del Foso? ¡Vamos a averiguarlo!",
                    [0x70a710fe93868301UL] = "Solo relájate y haz lo que te salga natural.",
                    [0x716d631bdc4e252fUL] = "¡Vaya paliza! Damas y caballeros...",
                    [0x726248305e62397dUL] = "¡Siete, ocho!",
                    [0x737ebf3c0d67cbd4UL] = "Espero por tu bien que... ASEGURES los cuerpos. Hay muchos que querrían poner sus manos sobre esos especímenes.",
                    [0x745524d8e00450beUL] = "¡Vamos, sacos de carne! ¡Es la hora del espectáculo!",
                    [0x759cb1960641dd4bUL] = "¿Cuerpos?",
                    [0x76590b86f59c73cbUL] = "¡Bien, listillo, esta es tu última advertencia! Voy a contar hasta diez, ¡y más vale que te largues antes de que termine!",
                    [0x7cb05c036d2c4aa9UL] = "¡Uno!",
                    [0x82201369d24c01faUL] = "¡Terminado!\n¡Je je!",
                    [0x847673fe434aab35UL] = "¡Mátenlos a todos!",
                    [0x857671edfdba06d4UL] = "¡Eras una ESTRELLA! ¡Le dabas al público lo que quería! ¡Sin eso, qué eres? ¡Solo juguetes rotos e inútiles!",
                    [0x8593736b30e839c0UL] = "...¡LA ÚLTIMA BATALLA!",
                    [0x8d30cbd182017c10UL] = "¡23 muertes más y tendré mi propio programa de cocina!",
                    [0x8df489f87cc6a52cUL] = "¡Esto lo arreglará!",
                    [0x8e5f0f7f5c0cbb8aUL] = "¡Están acabados, superluchadores! ¡Nunca volverán a trabajar en esta ciudad!",
                    [0x8f1e57d77f5fb234UL] = "¡Extra, extra! ¡Estudio de TV en ruinas! ¡Amado presentador presuntamente muerto! ¡Programa número uno cancelado indefinidamente! ¡Léanlo todo! ¡Solo en el Sunny City Times!",
                    [0x90f99afdd0b387b5UL] = "¡Argh!",
                    [0x94371d46ab899fceUL] = "¡Idiotas! Si ese cristal no hubiera sido perfectamente indestructible...",
                    [0x96cfa4c69e8d418dUL] = "...¡LOS SUPERLUCHADORES!",
                    [0x97ba63e54f080fd7UL] = "¿Qué...?!",
                    [0x97c9b369d808ee00UL] = "¡Miedo escénico!\n¡Je je!",
                    [0x9d225ae156a9deb8UL] = "Piloto",
                    [0x9ed352df60c04af4UL] = "¡Tres!\n¡Je!",
                    [0xa298bb2dba5188a6UL] = "¡Vaya!",
                    [0xac82644893598f19UL] = "Ninguno encontrado, señor. La torre misma cayó sobre tres manzanas. Las unidades están en camino. Es un maldito desastre, señor.",
                    [0xaca9b9d39992fc48UL] = "¡DIEZ!",
                    [0xad1436378a5175c9UL] = "¿Por qué los superluchadores no pueden simplemente seguir las reglas?",
                    [0xae134444f7c26076UL] = "¡La hora del show!\n¡Je je!",
                    [0xb483ac5f4a34476eUL] = "¡Eh, todo parte del espectáculo, amigos! ¡Volvemos enseguida después de estos mensajes!",
                    [0xb78b4049d2165930UL] = "¿No ven que hacemos un servicio público? ¡Mantenemos el orden! ¡Sin Superluchadores, habría CAOS!",
                    [0xb81f65f163aea663UL] = "¡Buen trabajo! Tómate un respiro antes del próximo desafío.",
                    [0xc15f97b9f9a0bf19UL] = "¡Cinco!",
                    [0xc1956c95db4f1635UL] = "¡No muerde!\n¡Je je!",
                    [0xc285478a7ef5c1ddUL] = "¡Extra, extra! ¡Nuevos desarrollos! ¡Los culpables aún podrían estar sueltos! ¡Se busca en...",
                    [0xc4344d31c649a69aUL] = "¡Increíble! ¡El Equipo Azul sigue en pie! ¡Que siga la fiesta!",
                    [0xc5a3ed4ef701c31bUL] = "No hay salida más que hacia arriba.",
                    [0xc8814e7e4c55afbdUL] = "Voz del Altavoz",
                    [0xc8b4fbbda23d60d2UL] = "Damas y caballeros, ¿podrían dar la bienvenida al escenario a...",
                    [0xc8c63ccd03e9ac5cUL] = "Toda esta ciudad se está volviendo loca. Y está a punto de empeorar. Lo presiento.",
                    [0xcad5dabf8a1ecadcUL] = "Eh... ¿jefe?",
                    [0xcf8171b349c00823UL] = "¡JE JE JE!",
                    [0xd04ab4fb2986fad5UL] = "Ahora toca un merecido descanso. ¡Dulces sueños!",
                    [0xd0b4e6c8d948c128UL] = "¡Guardias! ¡DETÉNGANLOS!",
                    [0xd107308732c7068dUL] = "Matarme no cambiará nada. Solo soy la fachada... el tipo del traje elegante. Puedo ser reemplazado... ¡pero no dejaré que pase!",
                    [0xd1a5c5ce237089abUL] = "Entonces, ¿quieres hacer algo luego?",
                    [0xd25289172c636d65UL] = "¡El Equipo Azul es el vencedor!",
                    [0xd4bc894a27001cf2UL] = "Oooooh.\n...Sí, supongo que sí.",
                    [0xd7ae1a2beb4b3228UL] = "¡Esta vez sin cazadores, solo la flor y nata: superluchadores vitaminados y sedientos de sangre, ¡directos de los tanques!",
                    [0xd8a2da16e9c7b997UL] = "¡No... han... ganado!...",
                    [0xd9ce7ca456113fb7UL] = "Ahora, ¡veamos cómo se las apañan con potencia de verdad! Es hora de...",
                    [0xda4c2730e89389e5UL] = "¡Ahí están - ábrenles fuego!",
                    [0xe0b85b403f25d327UL] = "No de ESA manera, sargento.",
                    [0xe13045c4ba53f183UL] = "Telón... abajo...",
                    [0xe51e11442202a632UL] = "En algún lugar de Sunny City\n20XX",
                    [0xe8d08ca0c960add4UL] = "Vienen más soldados. Será mejor que sigas moviéndote.",
                    [0xea7831fb17de8c48UL] = "Se te acaba el tiempo. Ya vienen.",
                    [0xeee6f11d36af4eccUL] = "No querrás acabar como estos pobres desgraciados. Parece que les dio miedo escénico, ¡je je!",
                    [0xef6bff69b221b98dUL] = "¿Qué haría la gente, me pregunto, sin su preciado entretenimiento?",
                    [0xefe036c18f965932UL] = "¡Eso es todo, amigos! PERO no olviden sintonizar mañana, que es cuando empieza la pelea DE VERDAD.",
                    [0xf231e5083f325b35UL] = "¡Malditos desagradecidos! ¿Qué harían sin nosotros?",
                    [0xf34bbac8ee388f22UL] = "¡Eso DOLIÓ! ¡Voy a disfrutar matándote!",
                    [0xf4f217f8d4781209UL] = "¡Nueve!",
                    [0xf838cce5cc35ccdeUL] = "Es algo sobre lo que reflexionar, supongo.",
                    [0xf84fcce272aa881dUL] = "¡Maldición!",
                    [0xfb2d0576fdf4511fUL] = "¿Noche dura, eh?",
                    [0xfc2d3c1ce47a805eUL] = "¡Nos retiramos!",
                    [0xfdceebfbb5ed9ec2UL] = "¡Vienen más soldados! ¡Están atrapados aquí! ¡Más les vale rendirse!",
                    [0xfe9e91d49ea5398fUL] = "Esta es tu parada.",
                },
            },
        };
    }
